package com.primehr.security;import com.primehr.integration.administrative.*;import org.springframework.security.access.AccessDeniedException;import org.springframework.stereotype.Component;
@Component public class PerformancePolicyPermissionGuard{public static final String FEATURE="primehr.performance-policy";private final AdministrativeAuthorizationClient client;public PerformancePolicyPermissionGuard(AdministrativeAuthorizationClient c){client=c;}public void require(PrimeHrAction a,String token){requireAgencyWide(client.resolve(FEATURE,token),a);}static void requireAgencyWide(EffectiveFeaturePermission p,PrimeHrAction a){boolean allowed=p.administrator()||p.canAccess()&&switch(a){case ACCESS->true;case ADD->p.canAdd();case EDIT->p.canEdit();case PUBLISH->p.canPublish();case FINALIZE->p.canFinalize();default->false;};if(!allowed||!p.administrator()&&p.dataScope()!=PermissionDataScope.AGENCY_WIDE)throw new AccessDeniedException("Performance Management requires agency-wide permission");}}
